string? nom = args.Length > 0 ? args[0] : null;
if (string.IsNullOrWhiteSpace(nom))
{
    Console.WriteLine("Nom requis");
    return;
}
Console.WriteLine(nom.Trim().ToUpperInvariant());

using var source = new CancellationTokenSource();
source.CancelAfter(TimeSpan.FromMilliseconds(50));
try
{
    await Task.Delay(TimeSpan.FromSeconds(2), source.Token);
    Console.WriteLine("Terminé");
}
catch (OperationCanceledException) when (source.IsCancellationRequested)
{
    Console.WriteLine("Annulé");
}

